import AxeBuilder from "@axe-core/playwright";
import { expect, test } from "@playwright/test";
import { readdirSync } from "node:fs";

// The /recipes/ index (tasks.md P22-T27): generated by bin/generate-api-docs from the repository's recipes/.
const recipeCount = readdirSync("../recipes", { withFileTypes: true })
    .filter((d) => d.isDirectory())
    .flatMap((d) => readdirSync(`../recipes/${d.name}`).filter((f) => f.endsWith(".html"))).length;

test("lists every recipe, each with a keyboard-reachable code block and links to its components", async ({
    page,
}) => {
    await page.goto("/recipes/");
    await expect(page.getByRole("heading", { level: 1, name: "Recipes" })).toBeVisible();
    const recipes = page.locator("article.recipe");
    await expect(recipes).toHaveCount(recipeCount);
    const card = page.getByRole("article", { name: "Card: the whole card as one link" });
    await expect(card.getByRole("link", { name: "card", exact: true })).toHaveAttribute(
        "href",
        "/components/card/",
    );
    const code = card.locator("pre");
    await expect(code).toHaveAttribute("tabindex", "0");
    await expect(code).toContainText("data-lily-card-link");
});

test("its content passes axe", async ({ page }) => {
    await page.goto("/recipes/");
    await page.waitForLoadState("networkidle");
    // Scoped to the page's own content, as the other site tests are; the shared header is checked on its own.
    const results = await new AxeBuilder({ page })
        .include("main")
        .withTags(["wcag2a", "wcag2aa", "wcag21a", "wcag21aa", "wcag22aa"])
        .analyze();
    expect(results.violations).toEqual([]);
});
